1	import type { Metadata } from 'next'
2	import { redirect } from 'next/navigation'
3	import { createClient } from '@/lib/supabase/server'
4	import { getOnboardingState } from '@/app/actions/onboarding'
5	import { OnboardingWizard } from '@/components/onboarding/OnboardingWizard'
6	
7	export const metadata: Metadata = {
8	  title: 'Set up your studio',
9	}
10	
11	export default async function OnboardingPage() {
12	  const supabase = await createClient()
13	  const {
14	    data: { user },
15	  } = await supabase.auth.getUser()
16	
17	  if (!user) redirect('/login')
18	
19	  const snapshot = await getOnboardingState()
20	
21	  // Already fully onboarded → skip to dashboard
22	  if (snapshot.studio?.onboarded_at) {
23	    redirect('/dashboard')
24	  }
25	
26	  // No studio yet (edge case — signup trigger should have created one)
27	  if (!snapshot.studioId) {
28	    redirect('/dashboard')
29	  }
30	
31	  return (
32	    <OnboardingWizard
33	      studioId={snapshot.studioId}
34	      userId={user.id}
35	      resumeAt={snapshot.resumeAt}
36	      initialFullName={snapshot.fullName}
37	      initialStudio={snapshot.studio}
38	    />
39	  )
40	}
41	

